#include <iostream>
using namespace std;

int main() {
    int arr[5] = {10, 20, 30, 40, 50};
    int *p = arr;
    for (int i = 0; i < 5; i++) {
        cout << "*(p + " << i << ") = " << *(p + i) << endl;
    }
    p++;
    cout << "After p++: *p = " << *p << endl;
    p += 2;
    cout << "After p += 2: *p = " << *p << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int arr[6] = {5, 10, 15, 20, 25, 30};
    int *first = &arr[0];
    int *last = &arr[5];
    cout << "Elements between: " << last - first << endl;
    cout << "Bytes between: " << (long long)last - (long long)first << endl;
    cout << "first < last? " << (first < last) << endl;
    int *mid = first + 3;
    cout << "*mid = " << *mid << endl;
    cout << "mid - first = " << mid - first << endl;
    cout << "first + 5 == last? " << (first + 5 == last) << endl;
    return 0;
}

#include <iostream>
