practice.answer:
#include <iostream>
using namespace std;
int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    int *p = arr;
    int sum = 0;
    for (int i = 0; i < 5; i++) {
        sum = sum + *(p + i);
    }
    cout << sum << endl;
    return 0;
}

